            return div().into_any_element();
        };
        if segment.rows.steps.is_empty() {
            return div().into_any_element();
        }
        let shown = *shown;
        let toggle = h_flex()
            .id(("answer-steps", id))
            .gap_1p5()
            .items_center()
            .cursor_pointer()
            .text_sm()
            .text_color(muted)
            .child(
                Icon::new(if shown {
                    IconName::ChevronDown
                } else {
                    IconName::ChevronRight
                })
                .xsmall(),
